// Returns:
//   - key: A through Z, or # for anything else.
func titleJumpKey(titleSort, title string) string {
	s := strings.TrimSpace(titleSort)
	if s == "" {
		s = strings.TrimSpace(title)
	}

	if s == "" {
		return "#"
	}

	r := unicode.ToUpper([]rune(s)[0])
	if r >= 'A' && r <= 'Z' {
		return string(r)
	}

	return "#"
}

